package com.reg21meme.dross.boss.fire.cave;

import com.reg21meme.dross.Dross;
import java.util.List;
import net.minecraft.core.BlockPos;
import net.minecraft.resources.ResourceLocation;

/**
 * The hermit crab caves, one template each (generated by tools/fire/hermit_caves.py; don't edit by hand): the Cinder
 * Hermit's small dens, about 10 blocks down into the Cinder Wastes (the user's idea, October 31, 2026).
 * <p>
 * A cave is {@code dross:hermit_cave/<id>}, {@code width} x {@code depth} blocks and {@code layers} tall, the
 * ground block at layer {@code groundLayer}, its way in at the south: {@code doorX}, {@code doorZ} is the cell you
 * stand in to go in, on the ground (layer {@code groundLayer + 1}; the template's own coordinates). {@code probe} is
 * its darkest floor cell (template coordinates), lit so nothing spawns there; {@code lava} how many lava blocks it has
 * (each walled in under and on its four sides). {@code crabs} are its crab spots: the cells (template coordinates) a
 * Cinder Hermit's feet stand in, its middle, with a free box 7 wide, 6 tall and 7 deep round it.
 */
public final class HermitCaveDesigns
{
    private HermitCaveDesigns() {}

    public record Cave(String id, String name, String lore, int width, int depth, int layers, int groundLayer, int doorX,
                       int doorZ, int probeX, int probeY, int probeZ, int lava, List<BlockPos> crabs)
    {
        public ResourceLocation template()
        {
            return new ResourceLocation(Dross.MODID, "hermit_cave/" + id);
        }

        public BlockPos probe()
        {
            return new BlockPos(probeX, probeY, probeZ);
        }

        /** The cell you stand in to go in (template coordinates). */
        public BlockPos door()
        {
            return new BlockPos(doorX, groundLayer + 1, doorZ);
        }
    }

    /** Every cave, in order (their numbers: 1 the Sinkhole Den ... 7 the Steam Vent Burrows). */
    public static final List<Cave> CAVES = List.of(
            new Cave("sinkhole_den", "Sinkhole Den",
                    "A round hole open to the sky, about 13 across and 10 deep. A ledge spirals down its basalt wall to an ash floor with a pool of lava ringed in magma; under the rim it bells out into a wider den.",
                    29, 29, 20, 12, 14, 28, 24, 7, 11, 18,
                    List.of(new BlockPos(10, 3, 19), new BlockPos(9, 3, 11))),
            new Cave("tide_pools", "Lava Tide Pools",
                    "A low cave mouth in a slope of ash and basalt; a tunnel slopes down into a long hall where shallow pools of lava lie walled in along both sides, each under a basalt arch.",
                    29, 29, 20, 12, 14, 28, 14, 5, 20, 96,
                    List.of(new BlockPos(14, 3, 5), new BlockPos(14, 3, 12))),
            new Cave("shell_midden", "Shell Midden",
                    "A domed den down a crack of steps, its edges heaped with the crabs' spare shells: bells, painted pots, horned skulls, lanterns, braziers of lava, amethyst, obsidian shards and magma.",
                    29, 29, 20, 12, 14, 28, 14, 3, 11, 0,
                    List.of(new BlockPos(14, 3, 7), new BlockPos(18, 3, 15), new BlockPos(10, 3, 15))),
            new Cave("lava_tube", "Collapsed Lava Tube",
                    "An old lava tube under the ash, a channel of lava still trickling along it. In the middle its roof has fallen in: a slope of rubble leads down into it, and at each end it swells into a round crab nook.",
                    29, 29, 20, 12, 14, 28, 27, 3, 11, 15,
                    List.of(new BlockPos(6, 3, 12), new BlockPos(22, 3, 12), new BlockPos(14, 3, 12))),
            new Cave("basalt_geode", "Basalt Geode",
                    "A hollow like a geode's, down a narrow crack: a rind of smooth basalt, a lining of blackstone glinting with gold, and glowing orange crystals growing out of it, a seep of lava in its floor.",
                    29, 29, 20, 12, 14, 28, 7, 3, 9, 4,
                    List.of(new BlockPos(10, 3, 12), new BlockPos(18, 3, 12))),
            new Cave("bone_reef", "Bone Reef",
                    "A long den under great ribs of bone arching over it like a ribcage, its floor grown over like a coral reef with bone and dead fire coral, magma glowing at the ribs' roots and lava in the hollows between them.",
                    29, 29, 20, 12, 14, 28, 14, 3, 1, 32,
                    List.of(new BlockPos(14, 3, 5), new BlockPos(10, 3, 13), new BlockPos(18, 3, 13))),
            new Cave("steam_burrows", "Steam Vent Burrows",
                    "A round den round a Cinder Vent puffing smoke on a little mound of basalt and magma, and three burrows dug off it, a crab in each, the heat seeping up through vents and glowing cracks in their floors.",
                    29, 29, 20, 12, 14, 28, 10, 3, 10, 6,
                    List.of(new BlockPos(5, 3, 13), new BlockPos(23, 3, 13), new BlockPos(14, 3, 5))));
}
